select public.register_portal_session('Cost fixture');
do $$ declare b uuid; br uuid; i uuid; s uuid; r uuid; p uuid; req uuid:=gen_random_uuid(); payload jsonb;begin
 b:=public.create_initial_bakery('Cost bakery','Main');select id into br from public.branches where bakery_id=b;
 insert into public.ingredients(bakery_id,name,unit,reference_cost) values(b,'Harina','kg',2) returning id into i;
 insert into public.suppliers(bakery_id,name) values(b,'Supplier') returning id into s;
 perform public.record_stock_movement(b,br,i,gen_random_uuid(),'in',10,'Stock inicial');
 payload:=jsonb_build_array(jsonb_build_object('ingredient_id',i,'quantity',5,'unit_cost',5));
 p:=public.receive_purchase(b,br,s,req,payload);
 if (select reference_cost from public.ingredients where id=i)<>3 then raise exception 'Wrong weighted average';end if;
 if (select quantity from public.stock_balances where ingredient_id=i)<>15 then raise exception 'Wrong stock';end if;
 if (select count(*) from public.ingredient_cost_history)<>1 then raise exception 'Missing history';end if;
 if p<>public.receive_purchase(b,br,s,req,payload) or (select count(*) from public.ingredient_cost_history)<>1 then raise exception 'Duplicate receipt';end if;
 r:=public.create_recipe_version(b,'Pan',100,jsonb_build_array(jsonb_build_object('ingredient_id',i,'quantity',2)));
 perform public.complete_production(b,br,r,gen_random_uuid(),100);
 if (select reference_cost from public.production_batches where recipe_id=r)<>6 then raise exception 'Production cost not updated';end if;
 perform public.record_stock_movement(b,br,i,gen_random_uuid(),'out',13,'Agotar stock');
 perform public.receive_purchase(b,br,s,gen_random_uuid(),jsonb_build_array(jsonb_build_object('ingredient_id',i,'quantity',3,'unit_cost',7)));
 if (select reference_cost from public.ingredients where id=i)<>7 then raise exception 'Zero stock reset';end if;
 if (select reference_cost from public.production_batches where recipe_id=r)<>6 then raise exception 'Historic production changed';end if;
 begin update public.ingredient_cost_history set new_cost=0;raise exception 'Writable cost history';exception when insufficient_privilege then null;end;
 begin perform public.receive_purchase(b,br,s,gen_random_uuid(),jsonb_build_array(jsonb_build_object('ingredient_id',i,'quantity',1,'unit_cost',8),jsonb_build_object('ingredient_id',i,'quantity',1,'unit_cost',8)));raise exception 'Duplicate lines accepted';exception when unique_violation then null;end;
 if (select reference_cost from public.ingredients where id=i)<>7 or (select count(*) from public.ingredient_cost_history)<>2 or (select quantity from public.stock_balances where ingredient_id=i)<>3 then raise exception 'Purchase rollback failed';end if;
end $$;
